<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';Auth::requireRole('admin');$pageTitle='مدیریت KPI';$edit=null;
if(isset($_GET['delete'])&&Auth::verifyCsrf($_GET['csrf_token']??'')){Database::execute('DELETE FROM kpis WHERE id=?',[(int)$_GET['delete']]);flash('شاخص حذف شد.');redirect('/admin/kpis.php');}
if(isset($_GET['edit']))$edit=Database::fetch('SELECT * FROM kpis WHERE id=?',[(int)$_GET['edit']]);
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){flash('درخواست نامعتبر است.','danger');redirect('/admin/kpis.php');}$id=(int)($_POST['id']??0);$data=[$_POST['title'],$_POST['description'],(float)$_POST['weight'],$_POST['status']];if($id){Database::execute('UPDATE kpis SET title=?,description=?,weight=?,status=?,updated_at=NOW() WHERE id=?',[...$data,$id]);flash('شاخص بروزرسانی شد.');}else{Database::execute('INSERT INTO kpis (title,description,weight,status,created_by,created_at,updated_at) VALUES (?,?,?,?,?,NOW(),NOW())',[...$data,Auth::user()['id']]);flash('شاخص ایجاد شد.');}redirect('/admin/kpis.php');}
$items=Database::fetchAll('SELECT k.*, u.name creator FROM kpis k LEFT JOIN users u ON u.id=k.created_by ORDER BY k.id DESC');require __DIR__.'/../views/partials/admin-header.php';?>
<form class="card admin-form" method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="grid grid-2"><label class="form-field"><span>عنوان</span><input name="title" value="<?=e($edit['title']??'') ?>" required></label><label class="form-field"><span>وزن</span><input type="number" step="0.01" min="0" name="weight" value="<?=e($edit['weight']??'1')?>" required></label><label class="form-field"><span>وضعیت</span><select name="status"><option value="active" <?=($edit['status']??'')==='active'?'selected':''?>>active</option><option value="disabled" <?=($edit['status']??'')==='disabled'?'selected':''?>>disabled</option></select></label><label class="form-field"><span>توضیحات</span><textarea name="description"><?=e($edit['description']??'')?></textarea></label></div><button class="btn btn-primary">ذخیره</button><a class="btn" href="/admin/kpis.php">جدید</a></form>
<div class="table-wrap"><table><thead><tr><th>عنوان</th><th>وزن</th><th>وضعیت</th><th>سازنده</th><th>عملیات</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['title'])?></td><td><?=e($i['weight'])?></td><td><?=e($i['status'])?></td><td><?=e($i['creator'])?></td><td class="actions"><a class="btn btn-small" href="?edit=<?=$i['id']?>">ویرایش</a><a class="btn btn-small btn-danger" onclick="return confirm('حذف شود؟')" href="?delete=<?=$i['id']?>&csrf_token=<?=e(Auth::csrfToken())?>">حذف</a></td></tr><?php endforeach;?></tbody></table></div></section></main></div><script src="/assets/js/app.js"></script></body></html>
